mapper.select:
SELECT c.conv_id AS convId, COUNT(m.msg_id) AS unread
FROM im_conversation c
JOIN im_message m ON m.conv_id = c.conv_id
LEFT JOIN im_unread u ON u.conv_id = c.conv_id AND u.user_id = #{userId}
WHERE (c.user_a_id = #{userId} OR c.user_b_id = #{userId})
  AND m.sender_id != #{userId}
  AND COALESCE(m.recalled, 0) = 0
  AND m.msg_id > COALESCE(u.last_read_msg_id, 0)
AND c.tenant_id = #{tenantId}
GROUP BY c.conv_id

mapper.update:
UPDATE im_unread
SET unread_count = 0, last_read_msg_id = GREATEST(last_read_msg_id, #{msgId})
WHERE user_id = #{userId} AND conv_id = #{convId}

UPDATE im_unread u
JOIN im_conversation c ON c.conv_id = u.conv_id
SET u.unread_count = 0, u.last_read_msg_id = GREATEST(u.last_read_msg_id, COALESCE(c.last_msg_id, 0))
WHERE u.user_id = #{userId}
AND c.tenant_id = #{tenantId}
